from fractions import Fraction
import math

def alt_partial(n):
    """S_n of 1 - 1/2 + 1/3 - ... (n terms), as a float."""
    return sum((-1) ** (k + 1) / k for k in range(1, n + 1))

def terms_needed(eps):
    """Smallest n with 1/(n+1) < eps. eps is a Fraction."""
    n = 0
    while Fraction(1, n + 1) >= eps:
        n += 1
    return n

def actual_needed(eps):
    """Smallest n with |ln 2 - S_n| < eps (the true error)."""
    s, n = 0.0, 0
    while True:
        n += 1
        s += (-1) ** (n + 1) / n
        if abs(math.log(2) - s) < eps:
            return n
